/**
 * WASMCLGLFor
 * @class
 */
export class WASMCLGLFor {
    constructor(jsonIn) {
        this.id = null;
        //this.kernels = {};
        //this.vertexFragmentPrograms = {};
        this.calledArgs = {};
    }

    static mallocUintNumber(val) { // must be "number" (uint8_t *)
        let arr = new Uint8Array(1);
        arr[0] = val;
        const p = Module._malloc(1); // Module._malloc(value.length * value.BYTES_PER_ELEMENT);
        Module.HEAPU8.set(arr, p);
        return p;
    }

    static mallocUint8Array(value) { // must be "number" (uint8_t *)
        let arr = new Uint8Array(value);
        const p = Module._malloc(arr.length);
        Module.HEAPU8.set(arr, p); // 3=64, 2=32, 1=16, nothing=8

        return p;
    } // for Uint8Array you can use array directly . must be "array" (uint8_t *)

    static mallocUint16Array(value) { // must be "number" (uint16_t *)
        let arr = new Uint16Array(value);
        const p = Module._malloc(arr.length * arr.BYTES_PER_ELEMENT);
        Module.HEAPU16.set(arr, p >> 1); // 3=64, 2=32, 1=16, nothing=8

        return p;
    }

    static mallocFloat32Array(value) { // must be "number" (float *)
        let arr = new Float32Array(value);
        const p = Module._malloc(arr.length * arr.BYTES_PER_ELEMENT);
        Module.HEAPF32.set(arr, p >> 2); // 3=64, 2=32, 1=16, nothing=8

        return p;
    }

    static mallocCharArray(arr, charLength) { // must be "number" (char * output)
        let newOutput = "";
        for(let n=0; n < arr.length; n++) {
            let c = (arr[n] === null) ? "null" : arr[n];
            for(let nb=c.length; nb < charLength; nb++)
                c += " ";

            newOutput += c;
        }
        const p = Module._malloc(newOutput.length+1); // Module._malloc(value.length * value.BYTES_PER_ELEMENT);
        Module.stringToUTF8(newOutput, p, newOutput.length+1);

        return p;
    };

    /**
     * Add one WebCLGLKernel to the work
     * @param {Object} kernelJson
     */
    addKernel(kernelJson) {
        let conf = kernelJson.config;
        let idx = conf[0];
        let outArg = (conf[1] instanceof Array) ? conf[1] : [conf[1]];
        let kH = conf[2];
        let kS = conf[3];

        let drawMode = (kernelJson.drawMode != null) ? kernelJson.drawMode : 4;
        let depthTest = (kernelJson.depthTest != null) ? kernelJson.depthTest : true;
        let blend = (kernelJson.blend != null) ? kernelJson.blend : false;
        let blendEquation = (kernelJson.blendEquation != null) ? kernelJson.blendEquation : "FUNC_ADD";
        let blendSrcMode = (kernelJson.blendSrcMode != null) ? kernelJson.blendSrcMode : "SRC_ALPHA";
        let blendDstMode = (kernelJson.blendDstMode != null) ? kernelJson.blendDstMode : "ONE_MINUS_SRC_ALPHA";

        // string name
        // string output[]
        // int drawMode
        // bool depthTest
        // bool blend
        // string blendEquation
        // string blendSrcMode
        // string blendDstMode
        // string header
        // string source
        Module.ccall("addKernelR", null, [   "number", "string", "string", "number",
                "number", "boolean", "boolean",
                "string", "string", "string",
                "string", "string"],
            [   this.id, kernelJson.name, idx, WASMCLGLFor.mallocCharArray(outArg, 50),
                WASMCLGLFor.mallocUintNumber(drawMode), WASMCLGLFor.mallocUintNumber(depthTest), WASMCLGLFor.mallocUintNumber(blend),
                blendEquation, blendSrcMode, blendDstMode,
                kH, kS]);
    };

    /**
     * addGraphic
     * @param {Object} graphicJson
     */
    addGraphic(graphicJson) {
        let conf = graphicJson.config;
        let outArg = ["null"];
        let VFP_vertexH;
        let VFP_vertexS;
        let VFP_fragmentH;
        let VFP_fragmentS;
        if(conf.length === 5) {
            outArg = (conf[0] instanceof Array) ? conf[0] : [conf[0]];
            VFP_vertexH = conf[1];
            VFP_vertexS = conf[2];
            VFP_fragmentH = conf[3];
            VFP_fragmentS = conf[4];
        } else {
            VFP_vertexH = conf[0];
            VFP_vertexS = conf[1];
            VFP_fragmentH = conf[2];
            VFP_fragmentS = conf[3];
        }

        let drawMode = (graphicJson.drawMode != null) ? graphicJson.drawMode : 4;
        let depthTest = (graphicJson.depthTest != null) ? graphicJson.depthTest : true;
        let blend = (graphicJson.blend != null) ? graphicJson.blend : true;
        let blendEquation = (graphicJson.blendEquation != null) ? graphicJson.blendEquation : "FUNC_ADD";
        let blendSrcMode = (graphicJson.blendSrcMode != null) ? graphicJson.blendSrcMode : "SRC_ALPHA";
        let blendDstMode = (graphicJson.blendDstMode != null) ? graphicJson.blendDstMode : "ONE_MINUS_SRC_ALPHA";

        // string name
        // string output[]
        // int drawMode
        // bool depthTest
        // bool blend
        // string blendEquation
        // string blendSrcMode
        // string blendDstMode
        // string Vheader
        // string Vsource
        // string Fheader
        // string Fsource
        Module.ccall("addGraphicR", null, [  "number", "string", "number",
                "number", "boolean", "boolean",
                "string", "string", "string",
                "string", "string",
                "string", "string"],
            [   this.id, graphicJson.name, WASMCLGLFor.mallocCharArray(outArg, 50),
                WASMCLGLFor.mallocUintNumber(drawMode), WASMCLGLFor.mallocUintNumber(depthTest), WASMCLGLFor.mallocUintNumber(blend),
                blendEquation, blendSrcMode, blendDstMode,
                VFP_vertexH, VFP_vertexS,
                VFP_fragmentH, VFP_fragmentS]);
    };

    /**
     * fillArg
     * @param {String} argName
     * @param {Array<float>} clearColor
     */
    fillArg(argName, clearColor) {
        Module.ccall("fillArg", null, ["number", "string", "number"],
            [this.id, argName, WASMCLGLFor.mallocFloat32Array(clearColor)]);
    };

    argIsNull(argument) {
        return Module.ccall("argIsNull", "number", ["number", "string"], [this.id, argument]) === 1;
    }

    getArgBufferWidth(argument) {
        return Module.ccall("getArgBufferWidth", "number", ["number", "string"], [this.id, argument]);
    }

    /**
     * addArg
     * @param {String} argument
     */
    addArg(argument) {
        Module.ccall("addArg", null, ["number", "string"],
            [this.id, argument]);
    };

    /**
     * Get argument from other gpufor (instead of addArg & setArg)
     * @param {String} argument Argument to set
     * @param {WebCLGLFor} gpufor
     */
    getGPUForArg(argument, gpufor) {
        /*if(this.calledArgs.hasOwnProperty(argument) === false)
            this.calledArgs[argument] = [];
        if(this.calledArgs[argument].indexOf(gpufor) === -1)
            this.calledArgs[argument].push(gpufor);

        if(gpufor.calledArgs.hasOwnProperty(argument) === false)
            gpufor.calledArgs[argument] = [];
        if(gpufor.calledArgs[argument].indexOf(this) === -1)
            gpufor.calledArgs[argument].push(this);*/

        //for(let key in gpufor._args) {
        //    let argName = key.split(" ")[1];
        //    if(argName === argument) {
        //        this._args[key] = gpufor._args[key];
                //this._argsValues[argName] = gpufor._argsValues[argName];

                Module.ccall("getGPUForArg", null, ["number", "string", "number"],
                    [this.id, argument, gpufor.id]);

        //        break;
        //    }
        //}
    };

    /**
     * Assign value of a argument for all added Kernels and vertexFragmentPrograms
     * @param {String} argument Argument to set
     * @param {float|Array<float>|Float32Array|Uint8Array|WebGLTexture|HTMLImageElement} value
     * @param {Array<float2>} [overrideDimensions=new Array(){Math.sqrt(value.length), Math.sqrt(value.length)}]
     * @returns {float|Array<float>|Float32Array|Uint8Array|WebGLTexture|HTMLImageElement}
     */
    setArg(argument, value, overrideDimensions) {
        if(value !== undefined && value !== null) {
            if(argument === "indices") {
                this.setIndices(value);
            } else {
                let uniformFValue = (value.constructor === Array || value instanceof Float32Array === true) ? -0.989898 : value;
                let uniformArrayFValue = (value.constructor === Array || value instanceof Float32Array === true) ? value : [0.0];

                let arD = (overrideDimensions !== undefined && overrideDimensions !== null) ? overrideDimensions : [0, 0];

                Module.ccall("setArg", null, ["number", "string", "number", "number", "number", "number"],
                    [this.id, argument,
                        WASMCLGLFor.mallocFloat32Array([uniformFValue]),
                        WASMCLGLFor.mallocFloat32Array(uniformArrayFValue),
                        uniformArrayFValue.length,
                        WASMCLGLFor.mallocFloat32Array(arD)]);
            }
        }

        return value;
    };

    /**
     * Get Float32Array array from a argument
     * @param {String} argument
     * @returns {Float32Array}
     */
    readArg(argument) {
        let w = this.getArgBufferWidth(argument);
        let uniformArrayFValue = new Float32Array(w*w*4);
        let uniformArrayFValue_ptr = WASMCLGLFor.mallocFloat32Array(uniformArrayFValue);
        let result = Module.ccall("readBuffer", 'number', ["number", "string", "number"], [this.id, argument, uniformArrayFValue_ptr]);

        for(let v=0; v<(w*w*4); v++)
            uniformArrayFValue[v] = Module.HEAPF32[result/Float32Array.BYTES_PER_ELEMENT+v];

        Module._free(uniformArrayFValue_ptr);

        return uniformArrayFValue;
    };

    /**
     * Set indices for the geometry passed in vertexFragmentProgram
     * @param {Array<float>} arr
     */
    setIndices(arr) {
        // string argument (varnameC)
        // string type="FLOAT"|"FLOAT4"
        // bool linear
        // string mode="SAMPLER"|"ATTRIBUTE"|"VERTEX_INDEX"
        // uint16_t value (bufferU16)
        // int valueLength
        // bool flip
        // float overrideDimensions[]

        Module.ccall("setArgIndices", null, ["number", "string", "string", "boolean", "string", "number", "number"],
                                            [this.id, "indices", "FLOAT", false, "VERTEX_INDEX", WASMCLGLFor.mallocUint16Array(arr), arr.length]);
    };

    enableKernel(kernelNum) {
        //this.kernels[kernelNum.toString()|"0"].enabled = true;
        Module.ccall("enableKernel", null, ["number", "number"], [this.id, kernelNum]);
    };

    disableKernel(kernelNum) {
        //this.kernels[kernelNum.toString()|"0"].enabled = false;
        Module.ccall("disableKernel", null, ["number", "number"], [this.id, kernelNum]);
    };

    /*getKernel(name) {
        for(let key in this.kernels) {
            if(key === name)
                return this.kernels[key];
        }

        return null;
    };

    getAllKernels() {
        return this.kernels;
    };*/

    enableGraphic(graphicNum) {
        //this.vertexFragmentPrograms[graphicNum.toString()|"0"].enabled = true;
        Module.ccall("enableGraphic", null, ["number", "number"], [this.id, graphicNum]);
    };

    disableGraphic(graphicNum) {
        //this.vertexFragmentPrograms[graphicNum.toString()|"0"].enabled = false;
        Module.ccall("disableGraphic", null, ["number", "number"], [this.id, graphicNum]);
    };

    /*getVertexFragmentProgram(name) {
        for(let key in this.vertexFragmentPrograms) {
            if(key === name)
                return this.vertexFragmentPrograms[key];
        }

        return null;
    };

    getAllVertexFragmentProgram() {
        return this.vertexFragmentPrograms;
    };*/

    resetGLConf() {
        Module.ccall("resetGLConf", null, null, null);
    };

    clearContext() {
        Module.ccall("clearContext", null, null, null);
    };

    clearOutputFrameBuffers() {
        Module.ccall("clearOutputFrameBuffers", null, null, null);
    };

    destroyContext() {
        Module.ccall("destroyContext", null, null, null);
        Module.canvas = null;
    };

    processKernel(kernelId, outputToTemp, processCop) {
        Module.ccall("processKernel", null, ["number", "number", "bool", "bool"], [this.id, kernelId, false, processCop]);
    };

    /**
     * Process kernels
     * @param {boolean} [outputToTemp=null]
     */
    processKernels(outputToTemp) {
        Module.ccall("processKernels", null, ["number"], [this.id]);
    };

    /**
     * processGraphic
     * @param {String} [argumentInd=undefined] Argument for vertices count or undefined if argument "indices" exist
     **/
    processGraphic(argumentInd) {
        Module.ccall("processGraphic", null, ["number", "string"], [this.id, argumentInd]);
    };

    /**
     * initialize numeric
     */
    ini() {
        let argumentss = arguments[0];
        let args;
        let idx;
        let typOut;
        let code;
        if(argumentss.length > 4) {
            args = argumentss[0];
            idx = argumentss[1];
            typOut = argumentss[2];
            code = argumentss[3];
        } else {
            args = argumentss[0];
            idx = argumentss[1];
            typOut = "FLOAT";
            code = argumentss[2];
        }

        // args
        let buffLength = 0;
        for(let key in args) {
            this.addArg(key);
            this.setArg(key.split(" ")[1], args[key]);

            if(buffLength === 0 &&
                (args[key] instanceof Array || args[key] instanceof Float32Array || args[key] instanceof Uint8Array || args[key] instanceof HTMLImageElement))
                buffLength = args[key].length;
        }
        if(typOut==="FLOAT")
            this.addArg("float* result");
        else
            this.addArg("float4* result");

        this.setArg("result", new Float32Array(buffLength), null);

        // kernel
        this.addKernel({
            "type": "KERNEL",
            "name": "SIMPLE_KERNEL",
            "viewSource": false,
            "config": [idx, ["result"],
                '',
                code]});

        // proccess
        this.processKernels();

        Module.canvas.width = Math.ceil(Math.sqrt(buffLength));
        Module.canvas.height = Module.canvas.width;

        let uniformArrayFValue = new Float32Array(buffLength*4);
        let result = Module.ccall("readBuffer", 'number', ["number", "string", "number"], [this.id, "result", WASMCLGLFor.mallocFloat32Array(uniformArrayFValue)]);

        for(let v=0; v<buffLength*4; v++)
            uniformArrayFValue[v] = Module.HEAPF32[result/Float32Array.BYTES_PER_ELEMENT+v];

        if(typOut === "FLOAT") {
            let fd = new Float32Array(buffLength);
            for(let n=0, fn= buffLength; n < fn; n++)
                fd[n] = uniformArrayFValue[n*4];

            uniformArrayFValue = fd;
        }

        return uniformArrayFValue;
    };

    /**
     * initialize Graphic
     */
    iniG() {
        let argumentss = arguments[0]; // override
        let args = argumentss[1]; // first is context or canvas

        // args
        for(let key in args) {
            this.addArg(key);

            if(key === "indices") {
                if(args[key] !== null)
                    this.setIndices(args[key]);
            } else
                this.setArg(key.split(" ")[1], args[key]);
        }

        // kernel & graphics
        for(let i = 2; i < argumentss.length; i++) {
            if(argumentss[i].hasOwnProperty("type") === true) {
                if (argumentss[i].type === "KERNEL")
                    this.addKernel(argumentss[i]);
                else if (argumentss[i].type === "GRAPHIC") // VFP
                    this.addGraphic(argumentss[i]);
            }
        }
    };

}
global.WASMCLGLFor = WASMCLGLFor;
module.exports.WASMCLGLFor = WASMCLGLFor;

/**
 * gpufor_asm
 * @returns {WebCLGLFor|Array<float>}
 */
export function gpufor_asm() {
    let clglFor = new WASMCLGLFor();
    let _gl = null;
    if (arguments[0] instanceof HTMLCanvasElement || arguments[0] === null) {
        //_gl = WebCLGLUtils.getWebGLContextFromCanvas(arguments[0]);

        //clglFor.setCtx(_gl);
        //clglFor._webCLGL = new WebCLGL(_gl);

        const canvas = arguments[0];
        if(Module.canvas === undefined || Module.canvas === null) {
            let id = "wasmclgl";
            let index = 0;
            canvas.id = id;
            //targetElem.appendChild(canvas);
            //const context = canvas.getContext("webgl2");

            const idBuffer = Module._malloc(id.length + 1);
            Module.stringToUTF8(id, idBuffer, id.length + 1);
            Module.canvas = canvas;

            clglFor.id = Module.ccall("createContext", "number", ["number", "number", "number", "number"], [canvas.width, canvas.height, idBuffer, index]);
        } else {
            clglFor.id = Module.ccall("createWasmCLGLFor", "number", ["number", "number"], [Module.canvas.width, Module.canvas.height]);
        }

        clglFor.iniG(arguments);
        arguments[arguments.length-1](clglFor);
    } else {
        //_gl = WebCLGLUtils.getWebGLContextFromCanvas(document.createElement('canvas'), {antialias: false});

        //clglFor.setCtx(_gl);
        //clglFor._webCLGL = new WebCLGL(_gl);


        const canvas = document.createElement('canvas');
        let id = "wasmclgl";
        let index = 0;
        canvas.id = id;
        document.body.appendChild(canvas);
        //const context = canvas.getContext("webgl2");

        const idBuffer = Module._malloc(id.length + 1);
        Module.stringToUTF8(id, idBuffer, id.length + 1);
        Module.canvas = canvas;
        Module.ccall("createContext", "number", ["number", "number", "number", "number"], [canvas.width, canvas.height, idBuffer, index]);

        arguments[arguments.length-1](clglFor.ini(arguments));
    }
}
global.gpufor_asm = gpufor_asm;
module.exports.gpufor_asm = gpufor_asm;